<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;">    data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F47067;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#ADBAC7;"> f.read()</span></span>
